# GUENNOUN GROUP - mise a jour (cargo anime + effets de defilement)
# Usage : depuis la racine du projet (la ou se trouve package.json) :
#   powershell -ExecutionPolicy Bypass -File .\apply-ship.ps1
$ErrorActionPreference = "Stop"
$root = (Get-Location).Path
if (-not [IO.File]::Exists((Join-Path $root "package.json"))) {
  Write-Host "ERREUR : lance ce script depuis la racine du projet (dossier contenant package.json)." -ForegroundColor Red
  exit 1
}
function W([string]$rel, [string]$b64) {
  $full = Join-Path $root $rel
  [IO.Directory]::CreateDirectory([IO.Path]::GetDirectoryName($full)) | Out-Null
  [IO.File]::WriteAllBytes($full, [Convert]::FromBase64String($b64))
  Write-Host ("  OK  " + $rel)
}
Write-Host "Ecriture des fichiers..." -ForegroundColor Cyan
W ".env.example" ""
W ".gitignore" "bm9kZV9tb2R1bGVzCi5uZXh0Cm91dAouZW52LmxvY2FsCioudHNidWlsZGluZm8KbmV4dC1lbnYuZC50cwo="
